let opportunities = null;

if (input.array && Array.isArray(input.array)) opportunities = input.array;
else if (input.opportunities && Array.isArray(input.opportunities)) opportunities = input.opportunities;
else if (input.opportunity && Array.isArray(input.opportunity)) opportunities = input.opportunity;
else if (Array.isArray(input)) opportunities = input;
else if (input.data && Array.isArray(input.data)) opportunities = input.data;
else opportunities = [input];

if (!opportunities || opportunities.length === 0) return [];

const STAGE_NAMES = {
  '8fc931f4-4694-42aa-a56e-cb80ff314460': '1. Unregistered | Pending Finance',
  '5a5c4474-150b-48bc-ba3c-a172c415ea1a': '2. SMSF /SINGLE CONTRACT',
  '30daaf81-e148-4217-a121-d624cc565ced': '3. No val access',
  'ab0ee0bb-9b05-4cfc-975a-749d565f03fc': '4. Pending Finance',
  'e6db59ed-b1c4-48cc-9ec3-587d23336691': '5. Valuation Ordered',
  'c99d0135-cd6a-467a-bb47-eac2f6d494b5': '6. Application Lodged',
  '2befdf02-7a80-4e9f-8766-8052a6f6cd93': '7. Formal Approval/unregistered',
  '22a44a98-f33b-4e18-a50d-325e47106419': '8. Formal Approval',
  '8c6fd147-88ac-4991-aa94-c5b13bce7e4f': '9. Settled'
};

const SETTLED_STAGE_ID = '8c6fd147-88ac-4991-aa94-c5b13bce7e4f';

const flattenCustomFields = (opp) => {
  const out = {};
  for (const cf of (opp.customFields || [])) {
    let val = "";
    if (cf.fieldValueString !== undefined && cf.fieldValueString !== null && cf.fieldValueString !== "") {
      val = cf.fieldValueString;
    } else if (Array.isArray(cf.fieldValueArray) && cf.fieldValueArray.length > 0) {
      val = cf.fieldValueArray.join(", ");
    } else if (cf.fieldValueDate !== undefined && cf.fieldValueDate !== null && cf.fieldValueDate !== "") {
      const d = new Date(cf.fieldValueDate);
      val = isNaN(d.getTime()) ? cf.fieldValueDate.toString() : d.toISOString().substring(0, 10);
    } else if (cf.fieldValueNumeric !== undefined && cf.fieldValueNumeric !== null && cf.fieldValueNumeric !== "") {
      val = cf.fieldValueNumeric.toString();
    } else if (cf.fieldValue !== undefined && cf.fieldValue !== null && cf.fieldValue !== "") {
      val = cf.fieldValue;
    }
    out[cf.id] = (val || "").toString().trim();
  }
  out["__owner"] = (opp.assignedTo || "").toString().trim();
  out["__followers"] = Array.isArray(opp.followers) ? opp.followers.filter(Boolean).join(",") : (opp.followers || "").toString().trim();
  return out;
};

const extractNotes = (raw) => {
  if (!raw) return "";
  if (Array.isArray(raw)) {
    return raw.map(n => (n && (n.body || n.text)) || "").filter(Boolean).join(" | ");
  }
  return raw.toString().trim();
};

const rows = [];

for (const opp of opportunities) {
  if (!opp || typeof opp !== "object") continue;

  const pipelineStageId = (opp.pipelineStageId || "").toString().trim();
  if (pipelineStageId === SETTLED_STAGE_ID) continue;

  const stageName = STAGE_NAMES[pipelineStageId] || "";
  const opportunityName = (opp.name || opp.title || "").toString().trim();
  const opportunityId = (opp.id || "").toString().trim();
  const monetaryValue = (opp.monetaryValue ?? "").toString();
  const status = (opp.status || "").toString();
  const createdAt = (opp.createdAt || "").toString();
  const updatedAt = (opp.updatedAt || "").toString();
  const lastStageChangeAt = (opp.lastStageChangeAt || "").toString();
  const contactName = (opp.contact?.name || opp.contact?.fullName || "").toString();
  const contactEmail = (opp.contact?.email || "").toString();
  const contactPhone = (opp.contact?.phone || "").toString();
  const notes = extractNotes(opp.notes);
  const customFieldsJson = JSON.stringify(flattenCustomFields(opp));

  rows.push({
    values: [
      stageName, opportunityName, monetaryValue, status, contactName,
      contactEmail, contactPhone, createdAt, updatedAt, lastStageChangeAt,
      pipelineStageId, opportunityId, notes, customFieldsJson
    ]
  });
}

return rows;

